/** Raised for an input the specification rejects. */
export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = new Map([
  ['http', '80'],
  ['ws', '80'],
  ['https', '443'],
  ['wss', '443'],
  ['ftp', '21'],
])

const HEX = '0123456789abcdefABCDEF'

function isHex(ch) {
  return ch !== undefined && HEX.includes(ch)
}

function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) || // A-Z
    (code >= 0x61 && code <= 0x7a) || // a-z
    (code >= 0x30 && code <= 0x39) || // 0-9
    code === 0x2d || // -
    code === 0x2e || // .
    code === 0x5f || // _
    code === 0x7e // ~
  )
}

function lowerAscii(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.charCodeAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 32) : ch
  }
  return out
}

/** Throws when `text` holds a `%` that is not followed by two hex digits. */
function checkPercent(text, component) {
  if (text === null || text === undefined) return
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] !== '%') continue
    if (!isHex(text[i + 1]) || !isHex(text[i + 2])) throw new UriError(component)
  }
}

/** Uppercases every `%XX` and decodes the ones that encode unreserved characters. */
function normalizePercent(text) {
  if (text === null || text === undefined) return text
  let out = ''
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === '%' && isHex(text[i + 1]) && isHex(text[i + 2])) {
      const digits = text.slice(i + 1, i + 3).toUpperCase()
      const code = parseInt(digits, 16)
      out += isUnreserved(code) ? String.fromCharCode(code) : `%${digits}`
      i += 2
    } else {
      out += text[i]
    }
  }
  return out
}

/**
 * Splits a URI reference into its five generic components. An absent
 * component is `null`; an empty one is the empty string.
 */
export function parse(reference) {
  let rest = reference
  let scheme = null

  const colon = rest.indexOf(':')
  if (colon >= 0 && !/[/?#]/.test(rest.slice(0, colon))) {
    scheme = rest.slice(0, colon)
    rest = rest.slice(colon + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    const end = rest.search(/[/?#]/)
    if (end < 0) {
      authority = rest
      rest = ''
    } else {
      authority = rest.slice(0, end)
      rest = rest.slice(end)
    }
  }

  let fragment = null
  const hash = rest.indexOf('#')
  if (hash >= 0) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }

  let query = null
  const mark = rest.indexOf('?')
  if (mark >= 0) {
    query = rest.slice(mark + 1)
    rest = rest.slice(0, mark)
  }

  return { scheme, authority, path: rest, query, fragment }
}

/** Splits an authority into userinfo, host and port. */
export function parseAuthority(authority) {
  if (authority === null) return { userinfo: null, host: null, port: null }
  let rest = authority
  let userinfo = null
  const at = rest.lastIndexOf('@')
  if (at >= 0) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }
  let port = null
  let host = rest
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket + 1)
  if (colon >= 0) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }
  return { userinfo, host, port }
}

function buildAuthority({ userinfo, host, port }) {
  let out = ''
  if (userinfo !== null) out += `${userinfo}@`
  out += host
  if (port !== null) out += `:${port}`
  return out
}

/** RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = `/${input.slice(3)}`
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      const cut = output.lastIndexOf('/')
      output = cut < 0 ? '' : output.slice(0, cut)
    } else if (input === '/..') {
      input = '/'
      const cut = output.lastIndexOf('/')
      output = cut < 0 ? '' : output.slice(0, cut)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input.indexOf('/', input.startsWith('/') ? 1 : 0)
      if (end < 0) end = input.length
      output += input.slice(0, end)
      input = input.slice(end)
    }
  }
  return output
}

/** Checks a parsed reference's components for truncated percent-encodings. */
export function checkComponents(parts) {
  const { userinfo, host } = parseAuthority(parts.authority)
  checkPercent(parts.path, 'path')
  checkPercent(userinfo, 'userinfo')
  checkPercent(host, 'host')
  checkPercent(parts.query, 'query')
  checkPercent(parts.fragment, 'fragment')
}

/** Normalizes parsed components and renders them back to a string. */
export function normalizeParts(parts) {
  const scheme = parts.scheme === null ? null : lowerAscii(parts.scheme)

  let authority = null
  if (parts.authority !== null) {
    const { userinfo, host, port } = parseAuthority(parts.authority)
    const pieces = {
      userinfo: normalizePercent(userinfo),
      host: lowerAscii(normalizePercent(host)),
      port,
    }
    if (port !== null) {
      const fallback = scheme === null ? undefined : DEFAULT_PORTS.get(scheme)
      if (port === '' || port === fallback) pieces.port = null
    }
    authority = buildAuthority(pieces)
  }

  let path = removeDotSegments(normalizePercent(parts.path))
  if (authority !== null && path === '') path = '/'

  const query = normalizePercent(parts.query)
  const fragment = normalizePercent(parts.fragment)

  let out = ''
  if (scheme !== null) out += `${scheme}:`
  if (authority !== null) out += `//${authority}`
  out += path
  if (query !== null) out += `?${query}`
  if (fragment !== null) out += `#${fragment}`
  return out
}

/** Normalizes a URI reference given as text. */
export function normalize(reference) {
  const parts = parse(reference)
  checkComponents(parts)
  return normalizeParts(parts)
}

function merge(base, refPath) {
  if (base.authority !== null && base.path === '') return `/${refPath}`
  const cut = base.path.lastIndexOf('/')
  if (cut < 0) return refPath
  return base.path.slice(0, cut + 1) + refPath
}

/** Resolves `reference` against `base` (strict RFC 3986 section 5.2.2). */
export function resolve(base, reference) {
  const b = parse(base)
  const r = parse(reference)
  checkComponents(b)
  checkComponents(r)

  const target = { scheme: null, authority: null, path: '', query: null, fragment: r.fragment }

  if (r.scheme !== null) {
    target.scheme = r.scheme
    target.authority = r.authority
    target.path = r.path
    target.query = r.query
  } else {
    target.scheme = b.scheme
    if (r.authority !== null) {
      target.authority = r.authority
      target.path = r.path
      target.query = r.query
    } else {
      target.authority = b.authority
      if (r.path === '') {
        target.path = b.path
        target.query = r.query === null ? b.query : r.query
      } else {
        target.path = r.path.startsWith('/') ? r.path : merge(b, r.path)
        target.query = r.query
      }
    }
  }

  return normalizeParts(target)
}

export { parse as parseReference }
