/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, parse, resolve, UriError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function splitRecords(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }

  const records = splitRecords(readStdin())
  const out = []

  for (let i = 0; i < records.length; i += 1) {
    const record = records[i]
    const line = i + 1
    try {
      if (mode === 'normalize') {
        out.push(normalize(record))
      } else {
        const space = record.indexOf(' ')
        if (space < 0) fail(`line ${line}: expected a base and a reference`)
        const base = record.slice(0, space)
        const reference = record.slice(space + 1)
        if (parse(base).scheme === null) fail(`line ${line}: the base has no scheme`)
        out.push(resolve(base, reference))
      }
    } catch (error) {
      if (error instanceof UriError) fail(`line ${line}: ${error.message}`)
      throw error
    }
  }

  process.stdout.write(out.map((entry) => `${entry}\n`).join(''))
}

main(process.argv.slice(2))
